package edu.pe.cibertec.saibm.usuario.infrastructure.in.rest; import java.util.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import edu.pe.cibertec.saibm.usuario.application.port.in.UserUseCase; @RestController @RequestMapping("/api/v1/users") public class UserController {private final UserUseCase use;private final TransitionalWriteAuthorizer auth;public UserController(UserUseCase u,TransitionalWriteAuthorizer a){use=u;auth=a;}@GetMapping List<UserUseCase.UserView> list(@RequestParam(defaultValue="")String q,HttpServletRequest h){return use.list(q,auth.actor(h));}@GetMapping("/{id}") UserUseCase.UserView find(@PathVariable UUID id,HttpServletRequest h){return use.find(id,auth.actor(h));}@PostMapping @ResponseStatus(HttpStatus.CREATED) UserUseCase.UserView create(@Valid @RequestBody Request r,@RequestHeader(value="X-Correlation-Id",defaultValue="")String c,HttpServletRequest h){auth.require(h);return use.create(r.command(),c);}@PutMapping("/{id}") UserUseCase.UserView update(@PathVariable UUID id,@Valid @RequestBody Request r,@RequestHeader(value="X-Correlation-Id",defaultValue="")String c,HttpServletRequest h){auth.require(h);return use.update(id,r.command(),auth.actor(h),c);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void deactivate(@PathVariable UUID id,@RequestHeader(value="X-Correlation-Id",defaultValue="")String c,HttpServletRequest h){auth.require(h);use.deactivate(id,auth.actor(h),c);}@PostMapping("/{id}/reactivate") UserUseCase.UserView reactivate(@PathVariable UUID id,@RequestHeader(value="X-Correlation-Id",defaultValue="")String c,HttpServletRequest h){auth.require(h);var actor=auth.actor(h);use.reactivate(id,actor,c);return use.find(id,new UserUseCase.Actor(actor.subject(),true));}record Request(@NotBlank @Size(max=100)String firstName,@NotBlank @Size(max=100)String lastName,@NotBlank @Size(max=20)String dni,@NotBlank @Email @Size(max=255)String email){UserUseCase.UserCommand command(){return new UserUseCase.UserCommand(firstName,lastName,dni,email);}}}
